GimCorpus.put(412,0,[[1,7,"וכל אלו שמקדימין וכו'. א\"א ואף בי\"ד עצמו מצוה בעשרה כרב אסי דהא רב גופיה דפליג עליה חש להא דרב אסי ומאי דכתב הרב ז\"ל בהלכות ודחה לרב אסי לאו מילתא היא דהיכא דאפשר למיהוי בעשרה מצוה למהדר עלייהו והיכא דלא אפשר ודאי קרי ביחיד, עכ\"ל:",1,0],[1,8,"תקנתו קלקלתו וכו'. א\"א כתב אותו ואין לו טעם ואולי מפני שאינו לא כפר ולא כלום וכן אמרו כפרים מקדימין וכן אמר מאימתי נעשית עיר הנדחת משהיו בה מעשרה עד מאה ופירש בירושלמי עיר לא כפר עיר לא כרך יותר ממאה כרך הוא עשרה כפר פחות מעשרה לא עיר ולא כפר, וכל זה אינו מספיק דלעולם אימא לך עשרה ופחות מעשרה כפר הוא עכ\"ל:",1,0],[1,14,"כיצד יום ארבעה עשר וכו'. א\"א כל זו הפסקא בשיבוש והרי היא מסודרת במשנה, עכ\"ל:",1,0],[2,18,"כל ספרי הנביאים וכו'. א\"א לא יבטל דבר מכל הספרים שאין ספר שאין בו למוד. אבל כך אמרו אפילו יבטלו שאר ספרים מלקרות בהם מגילה לא תבטל מלקרותה בצבור, עכ\"ל:",1,0],[3,5,"ולמה מברכין על יו\"ט שני וכו'. א\"א זה הטעם לאביי אבל רבא חלק עליו ואמר שאין הטעם לדמאי אלא מפני שרוב ע\"ה מעשרין הם אבל ספק אחר אפילו בדרבנן מברכין:",1,0],[3,6,"לעולם מדברי סופרים וכו'. א\"א ויש בהם עשה מדברי קבלה השיר יהיה לכם:",1,0],[3,7,"ומנהג זה בצבור וכו'. א\"א זה אינו כלום וכבר כתבנו עליו. ומה שכתב ליחיד שהתחיל לקרוא בדילוג לא אמר כלום אלא יקרא כמו שירצה וחותם כחתימת הצבור, עכ\"ל:",1,0],[4,9,"מנר חנוכה לנר חנוכה וכו'. אמר אברהם על ידי קינסא:",1,0]]);
